create table private.ai_reservations(job_id uuid primary key references public.outbox(id),school_id uuid not null references public.schools(id),kind text not null,created_at timestamptz not null default now());
alter table public.subscriptions add column insight_limit int not null default 1000 check(insight_limit>=0);
create or replace function public.runtime_reserve_ai(p jsonb)returns boolean language plpgsql security definer set search_path='' as $$declare s uuid:=(p->>'schoolId')::uuid;lim int;insight_cap int;used int;begin select ai_limit,insight_limit into lim,insight_cap from public.subscriptions where school_id=s and now()between starts_at and ends_at for update;if not found then return false;end if;if exists(select 1 from private.ai_reservations where job_id=(p->>'jobId')::uuid and school_id=s)then return true;end if;select coalesce(sum(u.used),0)into used from private.ai_usage u where u.school_id=s and month=date_trunc('month',now())::date;if used>=lim then return false;end if;if p->>'kind'='insight'and coalesce((select u.used from private.ai_usage u where u.school_id=s and month=date_trunc('month',now())::date and kind='insight'),0)>=insight_cap then return false;end if;insert into private.ai_reservations(job_id,school_id,kind)values((p->>'jobId')::uuid,s,p->>'kind');insert into private.ai_usage values(s,date_trunc('month',now())::date,p->>'kind',1)on conflict(school_id,month,kind)do update set used=ai_usage.used+1;return true;end$$;
alter table public.notifications add column obsolete boolean not null default false;
drop policy read_scope on public.notifications;
create policy read_scope on public.notifications for select to authenticated using(recipient_id=auth.uid()and school_id=private.school()and private.role()is not null and not obsolete);
create function private.cancel_query_reminders()returns trigger language plpgsql security definer set search_path='' as $$begin update public.notifications set obsolete=true where resource_id=new.query_id and type in('query.reminder','query.delayed')and (new.solution_delivered_at is not null or new.deadline_revision<>old.deadline_revision or new.student_resolved_at is not null);return new;end$$;
create trigger cancel_reminders after update on public.query_cycles for each row execute function private.cancel_query_reminders();
create function private.support_expiry()returns trigger language plpgsql security definer set search_path='' as $$begin if old.ended_at is null and new.ended_at is not null then insert into public.audit_events(school_id,actor_id,actor_role,subject_id,action,reason)select new.school_id,new.actor_id,role,new.student_id,'account.support.ended',new.reason from public.memberships where id=new.actor_id;end if;return new;end$$;
create trigger support_end after update on private.support_sessions for each row execute function private.support_expiry();
create function public.end_support(p jsonb)returns void language plpgsql security definer set search_path='' as $$begin update private.support_sessions set ended_at=now()where id=(p->>'id')::uuid and actor_id=auth.uid()and ended_at is null;end$$;
create function public.runtime_cleanup(p jsonb)returns jsonb language plpgsql security definer set search_path='' as $$declare keys jsonb;begin update private.support_sessions set ended_at=now()where ended_at is null and expires_at<=now();with expired as(update public.report_exports set status='expired'where expires_at<=now()and status<>'expired'returning object_key)select coalesce(jsonb_agg(object_key)filter(where object_key is not null),'[]')into keys from expired;update private.sessions set revoked_at=now()where revoked_at is null and expires_at<=now();return keys;end$$;
create table public.exam_managers(school_id uuid not null,version_id uuid not null,teacher_id uuid not null,primary key(version_id,teacher_id),foreign key(school_id,version_id)references public.exam_versions(school_id,id),foreign key(school_id,teacher_id)references public.memberships(school_id,id));
alter table public.exam_managers enable row level security;
create policy read_scope on public.exam_managers for select to authenticated using(school_id=private.school()and (teacher_id=auth.uid()and private.role()='teacher'or private.role()='administrator'));
grant select on public.exam_managers to authenticated;
create or replace function private.exam_teacher(v uuid)returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.exam_versions e where e.id=v and e.school_id=private.school()and private.role()='teacher'and (e.teacher_id=auth.uid()or exists(select 1 from public.exam_managers where version_id=v and teacher_id=auth.uid()))and private.assigned(e.class_id,e.subject))$$;
create function public.reassign_resource(p jsonb)returns void language plpgsql security definer set search_path='' as $$declare s uuid:=private.school();u uuid:=(p->>'teacherId')::uuid;i uuid:=(p->>'id')::uuid;c uuid;sub text;begin perform private.require_access(s);if private.role()<>'administrator'or length(coalesce(p->>'reason',''))=0 or not exists(select 1 from public.memberships where id=u and school_id=s and role='teacher'and active)then raise exception 'FORBIDDEN'using errcode='42501';end if;
if p->>'kind'='group'then select class_id,subject into c,sub from public.groups where id=i and school_id=s;elsif p->>'kind'='query'then select class_id,subject into c,sub from public.queries where id=i and school_id=s;elsif p->>'kind'='exam'then select class_id,subject into c,sub from public.exam_versions where id=i and school_id=s;else raise exception 'INVALID_KIND';end if;
if not exists(select 1 from public.teacher_assignments where teacher_id=u and class_id=c and subject=sub)then raise exception 'TEACHER_UNASSIGNED';end if;
if p->>'kind'='group'then update public.groups set teacher_id=u where id=i;elsif p->>'kind'='query'then update public.queries set teacher_id=u where id=i;insert into public.notifications(school_id,recipient_id,event_key,type,resource_id)select s,student_id,'query-reassigned:'||gen_random_uuid(),'query.reassigned',i from public.queries where id=i;else insert into public.exam_managers values(s,i,u)on conflict do nothing;end if;perform private.audit(s,'resource.reassigned',i,p->>'reason',jsonb_build_object('teacherId',u));end$$;
revoke execute on function public.end_support(jsonb),public.runtime_cleanup(jsonb),public.reassign_resource(jsonb)from public,anon,authenticated;grant execute on function public.end_support(jsonb),public.reassign_resource(jsonb)to authenticated;grant execute on function public.runtime_cleanup(jsonb)to service_role;
